<?php require_once __DIR__.'/auth.php'; $title='Tour Packages'; include 'admin-head.php'; include 'sidebar.php'; include 'topbar.php'; ?><main class="main"><?php
$items=read_data('packages');
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['id']??0); $action=$_POST['action']??'save';
 if($action==='delete'){ $items=array_values(array_filter($items,fn($x)=>(int)($x['id']??0)!==$id)); write_data('packages',$items); redirect('packages.php'); }
 $image=trim($_POST['image']??''); if($up=save_uploaded_image('image_file'))$image=$up; if($image==='')$image='srilanka.jpg';
 $record=['id'=>$id?:next_id($items),'title'=>trim($_POST['title']??''),'subtitle'=>trim($_POST['subtitle']??''),'type'=>trim($_POST['type']??'Tour'),'image'=>$image,'price'=>trim($_POST['price']??''),'color'=>'success','highlights'=>array_values(array_filter(array_map('trim',explode(',',$_POST['highlights']??'')))),'itinerary'=>array_values(array_filter(array_map('trim',explode("\n",$_POST['itinerary']??''))))];
 if($id){foreach($items as &$x)if((int)($x['id']??0)===$id)$x=$record;unset($x);}else $items[]=$record; write_data('packages',$items); redirect('packages.php');
}
$edit=null;if(isset($_GET['edit']))foreach($items as $x)if((int)($x['id']??0)===(int)$_GET['edit'])$edit=$x;
?>
<div class="row g-4"><div class="col-lg-5"><div class="card shadow-sm p-4"><h5 class="fw-bold mb-3"><?= $edit?'Edit':'Add' ?> Package</h5><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="mb-3"><label class="form-label">Title *</label><input name="title" class="form-control" value="<?=e($edit['title']??'')?>" required></div><div class="mb-3"><label class="form-label">Subtitle</label><input name="subtitle" class="form-control" value="<?=e($edit['subtitle']??'')?>"></div><div class="row"><div class="col-6 mb-3"><label class="form-label">Type</label><input name="type" class="form-control" value="<?=e($edit['type']??'Tour')?>"></div><div class="col-6 mb-3"><label class="form-label">Price</label><input name="price" class="form-control" value="<?=e($edit['price']??'')?>"></div></div><div class="mb-3"><label class="form-label">Image URL / filename</label><input name="image" class="form-control" value="<?=e($edit['image']??'')?>" placeholder="https://... or srilanka.jpg"></div><div class="mb-3"><label class="form-label">Or upload image</label><input type="file" name="image_file" class="form-control" accept="image/*"></div><div class="mb-3"><label class="form-label">Highlights (comma separated)</label><textarea name="highlights" class="form-control" rows="3"><?=e(implode(', ', $edit['highlights']??[]))?></textarea></div><div class="mb-3"><label class="form-label">Itinerary (one day per line)</label><textarea name="itinerary" class="form-control" rows="5"><?=e(implode("\n", $edit['itinerary']??[]))?></textarea></div><button class="btn btn-success w-100">Save Package</button><?php if($edit): ?><a href="packages.php" class="btn btn-light w-100 mt-2">Cancel</a><?php endif;?></form></div></div><div class="col-lg-7"><div class="card shadow-sm"><div class="card-header bg-white fw-bold">Packages <span class="badge bg-success"><?=count($items)?></span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Package</th><th>Price</th><th></th></tr></thead><tbody><?php foreach($items as $x): ?><tr><td><img class="thumb me-2" src="<?=e(admin_asset($x['image']))?>"><strong><?=e($x['title'])?></strong><br><small class="text-muted"><?=e($x['type']??'')?></small></td><td><?=e($x['price']??'')?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$x['id']?>">Edit</a> <form class="d-inline" method="post" onsubmit="return confirm('Delete this package?')"><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><?php include 'admin-foot.php'; ?>